#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int type;
    int price;
} Item;

typedef struct {
    int price;
    int type;
    int version;
} Node;

static int compare_items(const void *a, const void *b) {
    const Item *x = (const Item *)a;
    const Item *y = (const Item *)b;
    if (x->type != y->type) return (x->type > y->type) - (x->type < y->type);
    return (x->price > y->price) - (x->price < y->price);
}

static int less_node(Node a, Node b) {
    if (a.price != b.price) return a.price < b.price;
    return a.type < b.type;
}

static void push(Node *heap, int *size, Node value) {
    int i = ++(*size);
    while (i > 1 && less_node(value, heap[i / 2])) {
        heap[i] = heap[i / 2];
        i /= 2;
    }
    heap[i] = value;
}

static Node pop(Node *heap, int *size) {
    Node result = heap[1];
    Node last = heap[(*size)--];
    if (*size > 0) {
        int i = 1;
        while (i * 2 <= *size) {
            int child = i * 2;
            if (child + 1 <= *size && less_node(heap[child + 1], heap[child]))
                child++;
            if (!less_node(heap[child], last)) break;
            heap[i] = heap[child];
            i = child;
        }
        heap[i] = last;
    }
    return result;
}

int main(void) {
    int N, T;
    if (scanf("%d %d", &N, &T) != 2) return 0;

    Item *items = malloc((size_t)N * sizeof(Item));
    for (int i = 0; i < N; i++) scanf("%d", &items[i].type);
    for (int i = 0; i < N; i++) scanf("%d", &items[i].price);

    qsort(items, N, sizeof(Item), compare_items);

    int *position = calloc((size_t)T + 1, sizeof(int));
    int *end = calloc((size_t)T + 1, sizeof(int));
    int *version = calloc((size_t)T + 1, sizeof(int));

    for (int i = 0; i < N;) {
        int type = items[i].type;
        position[type] = i;
        while (i < N && items[i].type == type) i++;
        end[type] = i;
    }

    Node *heap = malloc(((size_t)N + T + 1) * sizeof(Node));
    int heap_size = 0;
    for (int type = 1; type <= T; type++) {
        if (position[type] < end[type]) {
            Node node = {items[position[type]].price, type, version[type]};
            push(heap, &heap_size, node);
        }
    }

    int C;
    scanf("%d", &C);
    long long total = 0;

    for (int i = 0; i < C; i++) {
        int requested;
        scanf("%d", &requested);

        int type;
        if (requested != 0) {
            type = requested;
            if (position[type] >= end[type]) continue;
        } else {
            while (heap_size > 0) {
                Node top = heap[1];
                if (top.version == version[top.type] &&
                    position[top.type] < end[top.type]) break;
                pop(heap, &heap_size);
            }
            if (heap_size == 0) continue;
            Node top = pop(heap, &heap_size);
            type = top.type;
        }

        total += items[position[type]].price;
        position[type]++;
        version[type]++;

        if (position[type] < end[type]) {
            Node node = {items[position[type]].price, type, version[type]};
            push(heap, &heap_size, node);
        }
    }

    printf("%lld\n", total);

    free(items);
    free(position);
    free(end);
    free(version);
    free(heap);
    return 0;
}
